cat app/javascript/controllers/index.js && cat app/javascript/application.js && cat <<'EOF' > app/javascript/controllers/option_rows_controller.js
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["list", "template"]

  add() {
    const index = this.rows.length
    const num = index + 1
    const html = this.templateTarget.innerHTML
      .replace(/__INDEX__/g, String(index))
      .replace(/__NUM__/g, String(num))

    this.listTarget.insertAdjacentHTML("beforeend", html)
    this.renumber()

    const lastInput = this.rows[this.rows.length - 1]?.querySelector('input[type="text"]')
    lastInput?.focus()
  }

  remove(event) {
    const row = event.currentTarget.closest(".option-row")
    if (row) {
      row.remove()
      this.renumber()
    }
  }

  get rows() {
    return Array.from(this.listTarget.querySelectorAll(".option-row"))
  }

  renumber() {
    this.rows.forEach((row, index) => {
      const num = index + 1
      const textLabel = row.querySelector("[data-option-text-label]")
      const textInput = row.querySelector('input[type="text"]')
      const hiddenCorrect = row.querySelector('input[type="hidden"][data-option-correct-hidden]')
      const checkbox = row.querySelector('input[type="checkbox"]')
      const checkboxLabel = row.querySelector("[data-option-correct-label]")
      const removeButton = row.querySelector("[data-option-remove]")

      const textId = `question_option_${num}_body`
      const correctId = `question_option_${num}_correct`

      if (textLabel) {
        textLabel.setAttribute("for", textId)
        textLabel.textContent = `Option ${num}`
      }
      if (textInput) {
        textInput.id = textId
        textInput.name = `question[options_attributes][${index}][body]`
        textInput.setAttribute("aria-label", `Option ${num}`)
      }
      if (hiddenCorrect) {
        hiddenCorrect.name = `question[options_attributes][${index}][correct]`
      }
      if (checkbox) {
        checkbox.id = correctId
        checkbox.name = `question[options_attributes][${index}][correct]`
        checkbox.setAttribute("aria-label", `Option ${num} is correct`)
      }
      if (checkboxLabel) {
        checkboxLabel.setAttribute("for", correctId)
      }
      if (removeButton) {
        removeButton.setAttribute("aria-label", `Remove option ${num}`)
      }
    })
  }
}
EOF

